import { registerPlantIdentities, plantIdentity } from './plant-identity.js';
import { plantResources } from './plant-resources.js';
import { ANIMALS, PLANTS, HABITATS } from './biodiversity.js?revision=120';
import { CENTERS, groundHeight, waterHeight } from './habitat-world.js?revision=120';
import { ExpeditionEcology } from './field-ecology.js?revision=120';

import { attachRefuges } from './living-habitats.js?revision=120';
import { attachGardenBees } from './garden-bees.js?revision=120';

export function createExpeditionSimulations(world,tide=0){
registerPlantIdentities(world.plants);
const simulations=new Map(),agents=[];
HABITATS.forEach((h,i)=>{const sim=new ExpeditionEcology(h.id,719+i*100),c=CENTERS[h.id];sim.patches=world.plants.filter((p,n)=>p.habitat===h.id&&(p.garden||n%16===0||['tree','shrub'].includes(PLANTS[p.id].type))).map(p=>({uid:plantIdentity(p),individualId:plantIdentity(p),...plantResources(PLANTS[p.id]),instance:p,flowers:p.flowers?.map(q=>({...q,x:q.x-c.x,z:q.z-c.z})),x:p.x-c.x,z:p.z-c.z,perches:p.perches?.map(q=>({...q,x:q.x-c.x,z:q.z-c.z})),size:p.size,tree:PLANTS[p.id].type==='tree',aquatic:PLANTS[p.id].type==='aquatic',flower:plantResources(PLANTS[p.id]).pollen,low:['grass','herb'].includes(PLANTS[p.id].type),species:p.id}));for(const species of h.plants){const present=sim.patches.filter(p=>p.species===species);if(present.length>=3)continue;for(const p of world.plants.filter(p=>p.habitat===h.id&&p.id===species)){if(sim.patches.some(q=>q.species===species&&Math.hypot(q.x-(p.x-c.x),q.z-(p.z-c.z))<.01))continue;sim.patches.push({uid:plantIdentity(p),individualId:plantIdentity(p),...plantResources(PLANTS[p.id]),instance:p,flowers:p.flowers?.map(q=>({...q,x:q.x-c.x,z:q.z-c.z})),x:p.x-c.x,z:p.z-c.z,perches:p.perches?.map(q=>({...q,x:q.x-c.x,z:q.z-c.z})),size:p.size,tree:PLANTS[p.id].type==='tree',aquatic:PLANTS[p.id].type==='aquatic',flower:plantResources(PLANTS[p.id]).pollen,low:['grass','herb'].includes(PLANTS[p.id].type),species:p.id});if(sim.patches.filter(q=>q.species===species).length>=3)break;}}sim.terrain=(x,z)=>groundHeight(x+c.x,z+c.z);sim.water=(x,z)=>waterHeight(x+c.x,z+c.z,h.id,sim.externalTide??tide);sim.externalTide=tide;for(const a of sim.agents)if(ANIMALS[a.species].type==='fish'&&!sim.passable(a.x,a.z,ANIMALS[a.species],a)){for(let n=0;n<400;n++){const p=sim.zonePoint(ANIMALS[a.species],a.id,n+1);if(sim.passable(p.x,p.z,ANIMALS[a.species],a)){Object.assign(a,p,{homeX:p.x,homeZ:p.z});break;}}}for(const resource of ['worms','mussels','plankton','insects','fish','algae','detritus'])for(let n=0;n<9;n++){const exemplar=Object.values(ANIMALS).find(s=>s.habitats.includes(h.id)&&s.resource===resource);if(!exemplar)continue;const p=sim.zonePoint(exemplar,n,1);sim.patches.push({...p,uid:`food-${resource}-${n}`,resource,detritus:resource==='detritus',aquatic:resource==='algae',species:({algae:'Mikroalgen und Aufwuchs',detritus:'Organische Partikel im Sediment',worms:'Bodenwirbellose',mussels:'kleine Bodentiere',plankton:'Schwebstoffe',insects:'kleine Wirbellose',fish:'Fischressource'})[resource],size:.15,stock:1});}sim.setBlockers(world.collisions.filter(p=>Math.hypot(p.x-c.x,p.z-c.z)<105).map(p=>({...p,x:p.x-c.x,z:p.z-c.z})));sim.agents.forEach(a=>{a.offsetX=c.x;a.offsetZ=c.z;if(ANIMALS[a.species].form==='owl'&&ANIMALS[a.species].daytime==='night'){sim.chooseAction(a,ANIMALS[a.species]);a.flight=a.perchHeight||0;}});if(h.id==='city'&&world.hives?.length){const h=world.hives[0];attachGardenBees(sim,{...h,x:h.x-c.x,z:h.z-c.z});}attachRefuges(sim,world,c);sim.settleSeals();sim.enableProximityActivation();simulations.set(h.id,sim);agents.push(...sim.agents);});
return {simulations,agents};
}
